import logging
import time

from taf.hw.rf_attenuator.devices.radiorack.radiorack_8_220 import RadioRack8220


class RadioRack8200(RadioRack8220):
    MAX_SUPPORTED_ATTENUATION = 110
    MIN_SUPPORTED_ATTENUATION = 0

    def _write_wait_and_read(self, cmd):
        self.telnet.write_command(cmd)
        time.sleep(0.5)
        resp = self.telnet.read_command_output('ATT', read_method='until')
        logging.debug('The response of Sending command: {}'.format(resp))
        return resp

    def _set_multiple_ports_decibel_attenuation(self, ports, attenuation_values):
        attenuation_values = [int(x) for x in attenuation_values]
        cmd = "ATT " + ";".join(["{} {}".format(port, value) for port, value in zip(ports, attenuation_values)])
        self._write_wait_and_read(cmd)
        logging.info('Channels {} attenuation value is set to {}.'.format(ports, attenuation_values))
